function  [Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc] = AssembleSparseLaplace(iele,nnpe,np,ke,me,fe,Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc)%%  Called by MechMonics%% assembles elemental force and stiffness matrices into global counterparts% assuming sparse matrices    for  i=1:nnpe              ii = np(iele,i);                 Fsr(fc)=ii;         Fsv(fc)=fe(i);         fc=fc+1;                      for j=1:nnpe                        jj=np(iele,j);	                        Ksr(kc)=ii;             Ksc(kc)=jj;             Ksv(kc)=ke(i,j);             kc=kc+1;            Jsr(jc)=ii;             Jsc(jc)=jj;             Jsv(jc)=me(i,j);             jc=jc+1;                   end    end